+  const fullPath = path.join(root, id);
+
+  if (!fileExists(fullPath)) {
+    return undefined;
+  }
+
+  const contents = await fs.readFile(fullPath, `utf8`); // An id looks like `src/<theme>/<relativePath>`. The first segment is
