+  const [, theme, ...rest] = id.split(path.sep);
+  const filePath = rest.join(path.sep);
+  const resource = {
+    id,
+    theme,
+    path: filePath,
+    contents
+  };
+  resource._message = message(resource);
+  return resource;
+};
