+  console.log(`plan keys:`, Object.keys(createPlan))
+
+  const createResponse = await resource.create(context, initialObject)
+  const validateResult = Joi.validate(createResponse, { ...resource.schema, ...resourceSchema })
+  if (validateResult.error) throw new Error(`validate: ${validateResult.error}`)
+  console.log(`create:`, JSON.stringify(createResponse).slice(0,120))
+
+  const readResponse = await resource.read(context, createResponse.id)
+  const eq = JSON.stringify(readResponse) === JSON.stringify(createResponse)
+  console.log(`read === create:`, eq)
+  if (!eq) { console.log(`  read:`, JSON.stringify(readResponse)); console.log(`  create:`, JSON.stringify(createResponse)) }
+
+  const updatedResource = { ...readResponse, ...partialUpdate }
+  const updatePlan = await resource.plan(context, updatedResource)
+  const updateResponse = await resource.update(context, updatedResource)
+  console.log(`update ok`)
+
+  const destroyResponse = await resource.destroy(context, updateResponse)
+  console.log(`destroy:`, JSON.stringify(destroyResponse).slice(0,80))
+
+  const postDestroy = await resource.read(context, createResponse.id)
+  console.log(`postDestroyRead undefined:`, postDestroy === undefined)
+}
+
+async function main() {
