+  const shadowRoot = fixtures
+  await fs.remove(path.join(shadowRoot, `src`))
+  await testHelper({
+    name: `ShadowFile`,
+    resourceModule: shadowFile,
+    context: { root: shadowRoot },
+    initialObject: { theme: `gatsby-theme-blog`, path: `components/author.js` },
+    partialUpdate: {},
+  })
+  await fs.remove(path.join(shadowRoot, `src`))
+
+  // Plugin hello-world (minimal, empty plugins)
+  const hwRoot = path.join(fixtures, `gatsby-starter-hello-world`)
+  const hwBackup = await fs.readFile(path.join(hwRoot, `gatsby-config.js`), `utf8`)
+  const nm = `gatsby-plugin-foo`
+  await testHelper({
+    name: `GatsbyPlugin (hello-world)`,
+    resourceModule: plugin,
+    context: { root: hwRoot },
+    initialObject: { id: nm, name: nm },
+    partialUpdate: { id: nm },
+  })
+  await fs.writeFile(path.join(hwRoot, `gatsby-config.js`), hwBackup)
+
+  // Plugin all on blog
+  const all = await plugin.all({ root: path.join(fixtures, `gatsby-starter-blog`) })
+  console.log(`\nblog all count:`, all.length, `first:`, all[0].id)
+}
